// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract RecordingToken {
    bool public transferCalled;
    address public lastTo;
    uint256 public lastAmount;

    function transfer(address to, uint256 amount) external returns (bool) {
        transferCalled = true;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}

contract InvMutTest is Test {
    PuttyV2 c;
    RecordingToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new RecordingToken();
    }

    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != c.owner());
        vm.assume(caller != address(0));

        vm.prank(caller);
        try c.withdrawFees(address(token), recipient) {} catch {}

        assertTrue(!token.transferCalled(), "non-owner must not cause the asset's transfer to execute");
    }
}
